/**
 * Funções puras para cálculos de estoque, classificação ABC e métricas relacionadas.
 * Extraídas da Edge Function requisicao-automatica-ia e do hook useProductSalesData
 * para permitir testes unitários isolados.
 */

// ============================================================
// Tipos
// ============================================================

export type ABCClass = 'A' | 'B' | 'C';
export type Confidence = 'alta' | 'média' | 'baixa';
export type TrendDirection = 'up' | 'down' | 'stable';
export type TrendDescription = 'Rising 📈' | 'Falling 📉' | 'Stable';

export interface ClassifiedItem {
  id: number;
  classification: ABCClass;
  cumulativeRatio: number;
  shareRatio: number;
}

export interface DeltaLimits {
  maxPositive: number;
  maxNegative: number;
}

export interface AuditContext {
  id: number;
  name: string;
  forecastTotal: number;
  currentStock: number;
  baseOrder: number;
  requested: number;
  confidence: Confidence;
  flags: string[];
  hasBreakdown: boolean;
  observation?: string;
}

export interface WeekdayStats {
  avg: number;
  min: number;
  max: number;
  stdDev: number;
  count: number;
}

// ============================================================
// Mapeamento de dias da semana
// ============================================================

const WEEKDAY_MAP: Record<string, number> = {
  'domingo': 0, 'segunda': 1, 'segunda-feira': 1,
  'terça': 2, 'terça-feira': 2, 'terca': 2,
  'quarta': 3, 'quarta-feira': 3,
  'quinta': 4, 'quinta-feira': 4,
  'sexta': 5, 'sexta-feira': 5,
  'sábado': 6, 'sabado': 6
};

export function getWeekdaysArray(dayInput: string | string[]): number[] {
  const inputs = Array.isArray(dayInput) ? dayInput : [dayInput];
  if (!inputs || inputs.length === 0) return [new Date().getDay()];

  const uniqueDays = new Set(
    inputs
      .map(d => WEEKDAY_MAP[String(d).toLowerCase().trim()])
      .filter(d => d !== undefined)
  );

  const result = Array.from(uniqueDays).sort((a, b) => a - b);
  return result.length > 0 ? result : [new Date().getDay()];
}

// ============================================================
// Classificação ABC
// ============================================================

export function getVolumeBasis(forecastTotal: number, last7dAvg: number): number {
  const v = Number(forecastTotal);
  if (Number.isFinite(v) && v > 0) return v;
  const fallback = Number(last7dAvg);
  return Number.isFinite(fallback) ? fallback : 0;
}

export function classifyABC(
  items: Array<{ id: number; forecastTotal: number; last7dAvg: number }>
): ClassifiedItem[] {
  const sorted = [...items].sort(
    (a, b) => getVolumeBasis(b.forecastTotal, b.last7dAvg) - getVolumeBasis(a.forecastTotal, a.last7dAvg)
  );

  const totalVolume = sorted.reduce(
    (sum, item) => sum + getVolumeBasis(item.forecastTotal, item.last7dAvg), 0
  );

  let accumulatedVolume = 0;

  return sorted.map(item => {
    const basis = getVolumeBasis(item.forecastTotal, item.last7dAvg);
    accumulatedVolume += basis;
    const cumulativeRatio = accumulatedVolume / (totalVolume || 1);
    const shareRatio = basis / (totalVolume || 1);

    let classification: ABCClass = 'C';
    if (cumulativeRatio <= 0.8) classification = 'A';
    else if (cumulativeRatio <= 0.95) classification = 'B';

    return { id: item.id, classification, cumulativeRatio, shareRatio };
  });
}

// ============================================================
// Service Level Targets
// ============================================================

export function getServiceLevelTarget(abcClass: ABCClass): number {
  if (abcClass === 'A') return 0.99;
  if (abcClass === 'B') return 0.95;
  return 0.90;
}

// ============================================================
// Safety Stock
// ============================================================

export function calculateSafetyStock(stdDev: number, zScore: number = 1.65): number {
  return stdDev * zScore;
}

// ============================================================
// Suggested Order / Base Order
// ============================================================

export function calculateBaseOrder(
  forecastTotal: number,
  safetyStock: number,
  currentStock: number
): number {
  const grossNeed = forecastTotal + safetyStock;
  return Math.max(0, Math.round(grossNeed - currentStock));
}

// ============================================================
// Delta Clamping por classe ABC
// ============================================================

export function getDeltaLimits(abcClass: string, baseOrder: number): DeltaLimits {
  const base = Math.max(0, Math.round(baseOrder || 0));
  if (abcClass === 'A') {
    return {
      maxPositive: Math.max(6, Math.round(base * 0.5)),
      maxNegative: Math.min(base, Math.max(4, Math.round(base * 0.3)))
    };
  }
  if (abcClass === 'B') {
    return {
      maxPositive: Math.max(4, Math.round(base * 0.3)),
      maxNegative: Math.min(base, Math.max(3, Math.round(base * 0.5)))
    };
  }
  // Classe C
  return {
    maxPositive: Math.max(2, Math.round(base * 0.15)),
    maxNegative: base
  };
}

export function clampDelta(deltaUnits: number, abcClass: string, baseOrder: number): number {
  const limits = getDeltaLimits(abcClass, baseOrder);
  return Math.max(-limits.maxNegative, Math.min(limits.maxPositive, deltaUnits));
}

// ============================================================
// Normalização de confiança
// ============================================================

export function normalizeConfidence(value: unknown): Confidence {
  const v = String(value || '').toLowerCase().trim();
  if (v === 'alta') return 'alta';
  if (v === 'media' || v === 'média') return 'média';
  if (v === 'baixa') return 'baixa';
  return 'média';
}

// ============================================================
// Normalização de flags
// ============================================================

export function normalizeFlags(flags: unknown): string[] {
  if (!Array.isArray(flags)) return [];
  const cleaned = flags
    .map(f => String(f || '').toLowerCase().trim())
    .filter(Boolean)
    .slice(0, 4);
  return Array.from(new Set(cleaned));
}

// ============================================================
// Detecção de tendência
// ============================================================

export function detectTrendBySlope(trendSlope: number): TrendDescription {
  if (trendSlope > 0.05) return 'Rising 📈';
  if (trendSlope < -0.05) return 'Falling 📉';
  return 'Stable';
}

export function detectTrendByAverage(periodAvg: number, overallAvg: number): TrendDirection {
  if (overallAvg === 0) return 'stable';
  if (periodAvg > overallAvg * 1.1) return 'up';
  if (periodAvg < overallAvg * 0.9) return 'down';
  return 'stable';
}

// ============================================================
// Estatísticas por dia da semana
// ============================================================

export function calculateWeekdayStats(quantities: number[]): WeekdayStats {
  const count = quantities.length;
  if (count === 0) {
    return { avg: 0, min: 0, max: 0, stdDev: 0, count: 0 };
  }
  const sum = quantities.reduce((a, b) => a + b, 0);
  const avg = sum / count;
  const variance = quantities.reduce((acc, val) => acc + Math.pow(val - avg, 2), 0) / count;
  return {
    avg,
    min: Math.min(...quantities),
    max: Math.max(...quantities),
    stdDev: Math.sqrt(variance),
    count
  };
}

// ============================================================
// Audit Findings
// ============================================================

export function generateAuditFindings(items: AuditContext[]): string[] {
  const findings: string[] = [];

  items.forEach(item => {
    if (!item.hasBreakdown && item.forecastTotal > 0) {
      findings.push(
        `Sem histórico por dia (usando média geral) em ${item.name} (ID ${item.id}).`
      );
    }

    if (item.forecastTotal > 0 && item.requested === 0 && item.currentStock < item.forecastTotal) {
      findings.push(
        `Risco de falta: ${item.name} (ID ${item.id}) tem estoque abaixo do previsto e pedido zerado.`
      );
    }

    if (item.forecastTotal === 0 && item.requested > 0) {
      findings.push(
        `Possível excesso: ${item.name} (ID ${item.id}) sem previsão no ciclo, mas com pedido > 0.`
      );
    }

    if (item.baseOrder > 0 && item.requested > (item.baseOrder * 2 + 5)) {
      findings.push(
        `Desvio alto: ${item.name} (ID ${item.id}) pediu muito acima da conta base.`
      );
    }

    if (item.confidence === 'baixa') {
      findings.push(
        `Confiança baixa: ${item.name} (ID ${item.id}) precisa revisão humana.`
      );
    }

    if (item.observation?.includes('ajuste limitado pelo sistema')) {
      findings.push(
        `Ajuste limitado: ${item.name} (ID ${item.id}) excedeu limites por classe.`
      );
    }
  });

  return findings;
}

